import{_ as t,o as r,c as o,a4 as a}from"./chunks/framework.BOlBRgXm.js";const m=JSON.parse('{"title":"What is texmorph?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1791398882000}'),d={name:"guide/introduction.md"};function n(i,e,s,p,h,c){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="what-is-texmorph" tabindex="-1">What is texmorph? <a class="header-anchor" href="#what-is-texmorph" aria-label="Permalink to &quot;What is texmorph?&quot;">​</a></h1><p>texmorph animates one rendered formula into another: symbols that appear in both formulas fly to their new positions, symbols that disappear fade out, and new ones fade in.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>x² + y² = z²   ──▶   x² = z² − y²</span></span></code></pre></div><p>Unlike most animation libraries, texmorph <strong>does not own a clock</strong>. A morph is prepared once, and after that any frame is produced by calling <code>render(t)</code> with a progress value between 0 and 1. The same <code>t</code> always gives the same picture, regardless of which frames were rendered before. This makes texmorph a good fit for:</p><ul><li>slide decks and step-by-step derivations, where the host controls timing and navigation;</li><li>scroll- or slider-driven explanations, where users scrub back and forth;</li><li>timeline tools such as GSAP, where a tween drives progress;</li><li>video export, where frames are rendered out of order or in parallel (Remotion, headless browsers).</li></ul><h2 id="packages" tabindex="-1">Packages <a class="header-anchor" href="#packages" aria-label="Permalink to &quot;Packages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Use it for</th></tr></thead><tbody><tr><td><a href="/Texmorph/renderers/katex"><code>@texmorph/katex</code></a></td><td>Morphing formulas rendered with KaTeX. Includes <code>createMorph()</code> and a script-tag build.</td></tr><tr><td><a href="/Texmorph/renderers/mathjax"><code>@texmorph/mathjax</code></a></td><td>Morphing formulas rendered with MathJax 4 (SVG output).</td></tr><tr><td><a href="/Texmorph/integrations/gsap"><code>@texmorph/gsap</code></a></td><td>Driving a morph from GSAP tweens and timelines.</td></tr><tr><td><a href="/Texmorph/integrations/web-component"><code>@texmorph/element</code></a></td><td>A <code>&lt;tex-morph&gt;</code> custom element.</td></tr><tr><td><a href="/Texmorph/integrations/remotion"><code>@texmorph/remotion</code></a></td><td>A <code>&lt;TexMorph&gt;</code> component for Remotion videos.</td></tr><tr><td><a href="/Texmorph/api/dom"><code>@texmorph/dom</code></a></td><td>The renderer-agnostic DOM driver (used by the packages above; needed when writing your own renderer).</td></tr><tr><td><a href="/Texmorph/api/core"><code>@texmorph/core</code></a></td><td>Pure planning and sampling with no DOM dependency.</td></tr></tbody></table><p>Most applications install exactly one renderer package (<code>@texmorph/katex</code> or <code>@texmorph/mathjax</code>) and, optionally, one integration.</p><h2 id="browser-support" tabindex="-1">Browser support <a class="header-anchor" href="#browser-support" aria-label="Permalink to &quot;Browser support&quot;">​</a></h2><p>The current versions of Chrome, Edge, Firefox and Safari (desktop and mobile). <code>Intl.Segmenter</code> is required.</p>',10)])])}const u=t(d,[["render",n]]);export{m as __pageData,u as default};
